local SaddleMaker = {}
local PRODUCTS = {
    leather_pillion = { name = "Usnjeni sedež", leatherCost = 2, woodCost = 1, time = 2, cost = 30, comfort = 5, durability = 18, description = "Preprost usnjeni sedež za kmete." },
    padded_saddle = { name = "Blazirani sedec", leatherCost = 3, woolCost = 2, time = 4, cost = 90, comfort = 10, durability = 25, prestige = 1, description = "Blazirani sedec za daljše jahanje." },
    war_saddle = { name = "Vojaški sedec", leatherCost = 3, woodCost = 2, ironCost = 1, time = 6, cost = 220, comfort = 12, durability = 35, prestige = 3, description = "Vojaški sedec z železnim okvirjem." },
    silver_horn_saddle = { name = "Srebrnorogi sedec", leatherCost = 3, silverCost = 1, woodCost = 2, time = 8, cost = 480, comfort = 14, durability = 45, prestige = 7, happiness = 1, description = "Sedec s srebrno roko za plemiče." },
    embroidered_saddle = { name = "Vezeni sedec", leatherCost = 3, silkCost = 1, silverCost = 1, threadCost = 1, time = 10, cost = 950, comfort = 16, durability = 55, prestige = 14, happiness = 2, description = "Vezeni sedec za visoke plemiče." },
    royal_ceremonial_saddle = { name = "Kraljevski slovesni sedec", leatherCost = 4, goldCost = 2, silverCost = 1, silkCost = 2, jewelCost = 1, pearlCost = 1, time = 14, cost = 2200, comfort = 22, durability = 80, prestige = 50, happiness = 10, description = "Veliki kraljevski slovesni sedec z zlatim, draguljnim in bisernim okovjem za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Sedlarska delavnica", cost = { gold = 280, wood = 130 }, upkeep = 7, qualityBonus = 5 },
    leather_room = { name = "Usnjiška soba", cost = { gold = 850, wood = 220, stone = 200, leather = 8 }, upkeep = 20, qualityBonus = 18 },
    embroidery_room = { name = "Vezenilnica", cost = { gold = 1900, wood = 280, stone = 400, silver = 25, thread = 8 }, upkeep = 45, qualityBonus = 30 },
    royal_saddle_atelier = { name = "Kraljevski atelje sedlov", cost = { gold = 7500, wood = 500, stone = 800, gold = 50, jewel = 20 }, upkeep = 140, qualityBonus = 55, prestigeBonus = 33 },
}
SaddleMaker.leatherStock = 14; SaddleMaker.woodStock = 14; SaddleMaker.woolStock = 10; SaddleMaker.ironStock = 10; SaddleMaker.silverStock = 8; SaddleMaker.silkStock = 8; SaddleMaker.threadStock = 8; SaddleMaker.goldStock = 6; SaddleMaker.jewelStock = 6; SaddleMaker.pearlStock = 4
SaddleMaker.productStock = {}; SaddleMaker.buildings = {}; SaddleMaker.maker = nil; SaddleMaker.activeMaking = {}; SaddleMaker.totalProducts = 0; SaddleMaker.dayTimer = 0
function SaddleMaker.init() SaddleMaker.leatherStock=14; SaddleMaker.woodStock=14; SaddleMaker.woolStock=10; SaddleMaker.ironStock=10; SaddleMaker.silverStock=8; SaddleMaker.silkStock=8; SaddleMaker.threadStock=8; SaddleMaker.goldStock=6; SaddleMaker.jewelStock=6; SaddleMaker.pearlStock=4; SaddleMaker.productStock={}; SaddleMaker.buildings={}; SaddleMaker.maker=nil; SaddleMaker.activeMaking={}; SaddleMaker.totalProducts=0; SaddleMaker.dayTimer=0; print("[SaddleMaker] Royal Saddle Maker System initialized (6 products, 4 buildings)") end
function SaddleMaker.hireMaker(n,s) s=s or math.random(50,90); local c=500+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SaddleMaker.maker={name=n or ("Sedlar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sedlar najet: %s (spretnost: %d)",SaddleMaker.maker.name,s),"success") end; return true end
function SaddleMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SaddleMaker.build(id) local ok,e=SaddleMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SaddleMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SaddleMaker.getQualityBonus() local b=0; for _,bd in ipairs(SaddleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SaddleMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.leatherCost and SaddleMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.woodCost and SaddleMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.woolCost and SaddleMaker.woolStock<(d.woolCost or 0) then return false,"Premalo volne" end; if d.ironCost and SaddleMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.silverCost and SaddleMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.silkCost and SaddleMaker.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if d.threadCost and SaddleMaker.threadStock<(d.threadCost or 0) then return false,"Premalo niti" end; if d.goldCost and SaddleMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SaddleMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SaddleMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SaddleMaker.buildings==0 then return false,"Potrebna delavnica" end; if not SaddleMaker.maker then return false,"Potreben sedlar" end; return true end
function SaddleMaker.make(pt,qty) qty=qty or 1; local ok,e=SaddleMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.leatherCost then SaddleMaker.leatherStock=SaddleMaker.leatherStock-d.leatherCost*qty end; if d.woodCost then SaddleMaker.woodStock=SaddleMaker.woodStock-d.woodCost*qty end; if d.woolCost then SaddleMaker.woolStock=SaddleMaker.woolStock-d.woolCost*qty end; if d.ironCost then SaddleMaker.ironStock=SaddleMaker.ironStock-d.ironCost*qty end; if d.silverCost then SaddleMaker.silverStock=SaddleMaker.silverStock-d.silverCost*qty end; if d.silkCost then SaddleMaker.silkStock=SaddleMaker.silkStock-d.silkCost*qty end; if d.threadCost then SaddleMaker.threadStock=SaddleMaker.threadStock-d.threadCost*qty end; if d.goldCost then SaddleMaker.goldStock=SaddleMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SaddleMaker.jewelStock=SaddleMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SaddleMaker.pearlStock=SaddleMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SaddleMaker.maker then t=math.max(1,t-math.floor(SaddleMaker.maker.skill/12)) end; table.insert(SaddleMaker.activeMaking,{id="saddle_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,comfort=d.comfort or 0,durability=d.durability or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SaddleMaker.completeMaking(m) local q=1.0+(SaddleMaker.getQualityBonus()/100); if SaddleMaker.maker then q=q+(SaddleMaker.maker.skill/180) end; q=math.min(2.0,q); SaddleMaker.productStock[m.productType]=(SaddleMaker.productStock[m.productType] or 0)+m.quantity; SaddleMaker.totalProducts=SaddleMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SaddleMaker.maker then SaddleMaker.maker.itemsMade=SaddleMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then SaddleMaker.maker.skill=math.min(100,SaddleMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sedec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"saddle.completed",{productName=m.productName,comfort=m.comfort,durability=m.durability}) end end
function SaddleMaker.update(dt) if not _G.state then return end; SaddleMaker.dayTimer=SaddleMaker.dayTimer+dt; if SaddleMaker.dayTimer>=30 then SaddleMaker.dayTimer=0; for i=#SaddleMaker.activeMaking,1,-1 do local m=SaddleMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SaddleMaker.completeMaking(m); table.remove(SaddleMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SaddleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SaddleMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SaddleMaker.getStats() return {leatherStock=SaddleMaker.leatherStock,woodStock=SaddleMaker.woodStock,woolStock=SaddleMaker.woolStock,ironStock=SaddleMaker.ironStock,silverStock=SaddleMaker.silverStock,silkStock=SaddleMaker.silkStock,threadStock=SaddleMaker.threadStock,goldStock=SaddleMaker.goldStock,jewelStock=SaddleMaker.jewelStock,pearlStock=SaddleMaker.pearlStock,productStock=SaddleMaker.productStock,numBuildings=#SaddleMaker.buildings,hasMaker=SaddleMaker.maker~=nil,makerName=SaddleMaker.maker and SaddleMaker.maker.name or "—",makerSkill=SaddleMaker.maker and SaddleMaker.maker.skill or 0,activeMaking=#SaddleMaker.activeMaking,totalProducts=SaddleMaker.totalProducts} end
return SaddleMaker
